	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		QualityRule
	 */
		public QualityRule createQualityRule( CreateQualityRuleCommand command ) {

		QualityRule entity = new QualityRule();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setQualityRuleId( command.getQualityRuleId() );
            entity.setName( command.getName() );
            entity.setThreshold( command.getThreshold() );
            entity.setTargetField( command.getTargetField() );
            entity.setDimension( command.getDimension() );
            entity.setOperator( command.getOperator() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of QualityRule {0} ", entity.toString() );

		return entity;
	}

